func (h *BatchTransformHandler) detectPrimaryKey(execDB *gorm.DB, schemaName, tableName string) (string, error) {
	qualifiedName := fmt.Sprintf("%s.%s", quoteIdent(schemaName), quoteIdent(tableName))
	var pkCol string
	err := execDB.Raw(`
		SELECT a.attname
		FROM pg_index i
		JOIN pg_attribute a ON a.attrelid = i.indrelid AND a.attnum = ANY(i.indkey)
		WHERE i.indrelid = ?::regclass AND i.indisprimary
		ORDER BY array_position(i.indkey, a.attnum)
		LIMIT 1
	`, qualifiedName).Scan(&pkCol).Error
	if err != nil {
		return "", err
	}
	if pkCol == "" {
		return "", fmt.Errorf("table %s.%s has no primary key", schemaName, tableName)
	}
	return pkCol, nil
}

